import os
import hashlib
from datetime import datetime

def compute_hex_digest(file_path):
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return sha256.hexdigest()
    except IOError:
        return None

def process_file(path):
    if not os.path.exists(path):
        return False, "Missing file: {}".format(path)
    try:
        with open(path, 'rb') as f:
            pass  # Just check if it's readable
        digest = compute_hex_digest(path)
        if digest is not None:
            return True, digest
        return False, "Unreadable file: {}".format(path)
    except IOError:
        return False, "Unreadable file: {}".format(path)

def main():
    input_paths = []
    try:
        with open('input_paths.txt', 'r') as f:
            input_paths = [line.strip() for line in f if line.strip()]
    except IOError:
        print("ERROR: Could not read input_paths.txt")
        return

    manifest_lines = []
    errors = []
    timestamp = datetime.utcnow().isoformat()

    for path in input_paths:
        success, message = process_file(path)
        if success:
            digest = message
            manifest_lines.append(f"{path}\t{digest}")
            log_entry = f"{timestamp} INFO Processed {path}"
            print(log_entry)
        else:
            errors.append(message)
            log_entry = f"{timestamp} ERROR {message}"
            print(log_entry)

    with open('manifest.txt', 'w') as f:
        f.write('\n'.join(manifest_lines))

    with open('digest.log', 'a') as f:
        f.write(f"{timestamp} INFO Completed: {len(manifest_lines)} processed, {len(errors)} errors\n")

if __name__ == "__main__":
    main()

import os
import hashlib
import sys

def compute_file_digest(file_path):
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (IOError, OSError):
        return None

def process_input():
    manifest_lines = 0
    error_lines = 0

    with open('input_paths.txt', 'r') as input_file:
        for line in input_file:
            path = line.strip()
            if not path:
                continue

            try:
                if os.path.exists(path):
                    digest = compute_file_digest(path)
                    if digest is not None:
                        with open('manifest.txt', 'a') as manifest:
                            manifest.write(f"{path}\t{digest}\n")
                        manifest_lines += 1
                        with open('digest.log', 'a') as log:
                            log.write(f"INFO Processed {path}\n")
                    else:
                        with open('digest.log', 'a') as log:
                            log.write(f"ERROR Unreadable file: {path}\n")
                        error_lines += 1
                else:
                    with open('digest.log', 'a') as log:
                        log.write(f"ERROR Missing file: {path}\n")
                    error_lines += 1
            except Exception:
                with open('digest.log', 'a') as log:
                    log.write(f"ERROR Unreadable file: {path}\n")
                error_lines += 1

    with open('digest.log', 'a') as log:
        log.write(f"Completed: {manifest_lines} processed, {error_lines} errors\n")

    if not os.path.exists('manifest.txt'):
        with open('manifest.txt', 'w'):
            pass
    if not os.path.exists('digest.log'):
        with open('digest.log', 'w'):
            pass

if __name__ == "__main__":
    process_input()

import os
import hashlib

def compute_hex_digest(file_path):
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (IOError, OSError):
        return None

def main():
    with open('input_paths.txt', 'r') as input_file:
        paths = [line.strip() for line in input_file if line.strip()]

    processed = 0
    errors = 0

    with open('digest.log', 'w') as log_file:
        for path in paths:
            if os.path.isfile(path):
                digest = compute_hex_digest(path)
                if digest is not None:
                    log_file.write(f"{path}\t{digest}\n")
                    processed += 1
                else:
                    log_file.write(f"ERROR {path}\n")
                    errors += 1
            else:
                log_file.write(f"ERROR {path}\n")
                errors += 1

    log_file.write(f"Completed: {processed} processed, {errors} errors\n")

if __name__ == "__main__":
    main()
